import math
import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    p = float(ctx["p"])
    x = torch.randn(shape, dtype=dtype, device=device)
    pdist = torch.pdist(x, p=p)
    grad = torch.ones_like(pdist) if p in (1.0, 2.0) else torch.randn_like(pdist)
    return {"grad": grad, "x": x, "pdist": pdist}


def run(grad, x, p, pdist):
    return torch.ops.aten._pdist_backward(grad, x, float(p), pdist)
